import React from "react";
import { FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette, FaBolt, FaUserGraduate, FaLeaf } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* PROJECTS */}
      <div className="section projects-section">
        <h2>My Projects</h2>

        <div className="projects-grid">

          <div className="project-card large">
            <div className="project-icon"><FaBolt /></div>
            <h3>EnergyPulse</h3>
            <p>
              Developed the frontend of an AI-driven smart home solution, creating a responsive dashboard that displays real-time biometric and energy data. The interface enables users to monitor and control devices easily, with a clean and intuitive design focused on personalized energy optimization and smooth interactions.
            </p>
            <p className="tech-stack">Tech: React.js</p>
          </div>

          <div className="project-card">
            <div className="project-icon"><FaUserGraduate /></div>
            <h3>Student Portal Management</h3>
            <p>
              Developed a full-stack Student Portal Management System using Java and Spring Boot, enabling efficient student record management, authentication, and academic information through a structured backend with an intuitive frontend interface.
            </p>
            <p className="tech-stack">
              Spring Boot, HTML, CSS, JavaScript, MySQL
            </p>
          </div>

          <div className="project-card">
            <div className="project-icon"><FaLeaf /></div>
            <h3>Farm2Fork</h3>
            <p>
              Built an intuitive and responsive frontend interface for Farm2Fork, enabling seamless interaction between farmers and consumers through well-structured product listings and smooth navigation.
            </p>
            <p className="tech-stack">Tech: HTML, CSS, JavaScript</p>
          </div>

          {/* COGNI FLOW - FIXED ICON STYLE */}
          <div className="project-card large highlight">
            <div className="project-icon">🧠</div>
            <h3>Cogni Flow</h3>
            <p>
              Designed a structured and interactive frontend system focused on cognitive flow-based learning experience.
              The interface enhances user engagement through clean UI transitions and logical content flow.
            </p>
            <p className="tech-stack">Tech: HTML, CSS, JavaScript</p>
          </div>

        </div>
      </div>

      {/* ACHIEVEMENTS */}
      <div className="section achievements-section">
        <h2>Achievements</h2>

        <div className="achievements-grid">

          <div className="achievement-card">
            <div className="achievement-icon"><FaTrophy /></div>
            <h3>Hackathons Won</h3>
            <p>Semifinalist in Smart India Hackathon (SIH) 2025.</p>
          </div>

          <div className="achievement-card">
            <div className="achievement-icon"><FaProjectDiagram /></div>
            <h3>Project Competitions</h3>
            <p>Won Best Project Award for Li-Fi technology innovation.</p>
          </div>

        </div>

        <div className="achievements-grid">

          <div className="achievement-card">
            <div className="achievement-icon"><FaCalendarAlt /></div>
            <h3>Tech Events</h3>
            <p>Organized Code Crunch coding competition.</p>
          </div>

          <div className="achievement-card">
            <div className="achievement-icon"><FaPalette /></div>
            <h3>Non Tech Events</h3>
            <p>Conducted Fun Spin Round event successfully.</p>
          </div>

        </div>

      </div>

      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 40px 10%;
          font-family: "Poppins", sans-serif;
          background: #0f172a;
          color: white;
        }

        h2 {
          font-size: 36px;
          margin-bottom: 30px;
          color: #38BDF8;
        }

        /* PROJECT GRID IMPROVED LAYOUT */
        .projects-grid {
          display: grid;
          grid-template-columns: repeat(12, 1fr);
          gap: 20px;
        }

        .project-card {
          grid-column: span 4;
          background: rgba(255,255,255,0.05);
          padding: 22px;
          border-radius: 16px;
          border: 1px solid rgba(56,189,248,0.25);
          box-shadow: 0 0 15px rgba(56,189,248,0.15);
          transition: 0.4s;
          display: flex;
          flex-direction: column;
          gap: 10px;
        }

        .project-card.large {
          grid-column: span 6;
        }

        .project-card.highlight {
          border: 1px solid #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        .project-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 25px rgba(56,189,248,0.5);
        }

        .project-icon {
          font-size: 30px;
          color: #38BDF8; /* SAME BLUE FIXED */
        }

        h3 {
          margin: 0;
          color: #e2e8f0;
        }

        p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .tech-stack {
          font-weight: 600;
          color: #38BDF8;
        }

        /* ACHIEVEMENTS */
        .achievements-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 20px;
          margin-bottom: 30px;
        }

        .achievement-card {
          display: flex;
          gap: 15px;
          background: rgba(255,255,255,0.05);
          padding: 20px;
          border-radius: 16px;
          border: 1px solid rgba(56,189,248,0.25);
        }

        .achievement-icon {
          font-size: 26px;
          color: #38BDF8;
        }

        @media (max-width: 900px) {
          .project-card,
          .project-card.large {
            grid-column: span 12;
          }

          .achievements-grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
